// app/main.js
const fs = require('fs');
const path = require('path');
const os = require('os');
const https = require('https');
const { pipeline } = require('stream');
const readline = require('readline');
const Cerebras = require('@cerebras/cerebras_cloud_sdk');
// API kulcsok
const apiKeys = [
  "csk-jw6drkvjmyfwfwxpfmc8rx32v6j8kpm93ymt8vdt8nw882vd",
  "csk-f2vt69wh63pkny4rd3pwdh88m2nyvm9yp8dwk9ynx2d83vfy",
  "csk-6k3jvehx4dr8524856ck5j32erjtjet86dxpy9fyd9nwedft"
];
const OUTPUT_FILE = path.join(__dirname, 'DuetQA-Verified-multilingual.jsonl');
const CHECKPOINT_FILE = path.join(__dirname, 'DuetQA-Verified-checkpoint.json');
// Cél nyelvek
const languages = [
  "magyar", "török", "finn", "észt", "tamil", "kannada", "telugu", "koreai", "japán", "zulu", 
  "szuahéli", "inuktitut", "st. lawrence island yupik", "yupik", "mohawk", "nahuatl", "orosz", 
  "izlandi", "szlovén", "arab", "perzsa", "urdu", "görög", "vietnami", "mandarin kínai", "angol", 
  "spanyol", "portugál", "hindí", "bengáli", "indonéz", "maláj", "ubyh", "grúz", "szuahéli", "zulu"
];
// 2 Core Cerebras model
const MODEL1 = "gpt-oss-120b";
const MODEL2 = "qwen-3-coder-480b";

function getAvailableApiKey(index) {
  return apiKeys[index % apiKeys.length];
}

// Dataset letöltése streammel, helytakarékosan:
function downloadDataset(url, dest) {
  return new Promise((resolve, reject) => {
    const file = fs.createWriteStream(dest);
    https.get(url, response => {
      if (response.statusCode !== 200) {
        return reject(new Error('HTTP ' + response.statusCode));
      }
      pipeline(response, file, err => err ? reject(err) : resolve());
    }).on('error', reject);
  });
}

// Visszatölt checkpoint (ha megszakadt)
function loadCheckpoint() {
  try {
    if (!fs.existsSync(CHECKPOINT_FILE)) return {};
    return JSON.parse(fs.readFileSync(CHECKPOINT_FILE, 'utf8'));
  } catch (e) { return {}; }
}
function saveCheckpoint(obj) {
  fs.writeFileSync(CHECKPOINT_FILE, JSON.stringify(obj, null, 2));
}

// Egy kérdés-válaszból összes nyelvi fordítás elkészítése és mentése
async function translateAndSaveAll(
  item, apiKeyIdx, checkpoint, writer, idx
) {
  let translations = {};
  // Elsődleges magyar model: gpt-oss-120b, a másodlagosok vegyesen qwen-3-coder-480b
  for (let li = 0; li < languages.length; ++li) {
    const lang = languages[li];
    let apiKey = getAvailableApiKey(apiKeyIdx + li);
    let model = (lang === "magyar") ? MODEL1 : MODEL2;
    let client = new Cerebras({ apiKey });
    const prompt = `Fordítsd le/natívan írd át a következő QA párost ezen a nyelven: ${lang}\n
Kérdés: "${item.question.strip ? item.question.strip() : item.question}"
Válasz: "${item.answer.strip ? item.answer.strip() : item.answer}"
Adj maximálisan informatív, grammatikailag hibátlan, anyanyelvi szintű, természetes és magabiztos fordítást a "${lang}" nyelvre! 

Csak a fordításokat válaszd vissza (pl. JSON objektum, pl.: {"question": "...", "answer": "..."})!`;

    let resp = '';
    try {
      const stream = await client.chat.completions.create({
        messages: [{ role: "system", content: "Te vagy a világ legprecízebb, hibátlan, természetes anyanyelvi szintű, informatív, high-quality fordítója." },
                   { role: "user", content: prompt }],
        model,
        stream: false,
        max_completion_tokens: 4096,
        temperature: 0.04,
        top_p: 0.02,
        reasoning_effort: "high"
      });
      // a választ lehet, hogy objectként adja vissza, lehet hogy stringként
      resp = (typeof resp === 'object') ? (resp.choices[0]?.message?.content || '') : resp;
      let translation = {};
      try {
        translation = JSON.parse(resp);
      } catch (e) {
        translation = { question: "HIBA: " + lang, answer: resp };
      }
      translations[lang] = translation;
    } catch (err) {
      translations[lang] = { question: `HIBA: ${lang}`, answer: "API hiba vagy rate limit: " + (err.message || err) };
    }
    checkpoint[idx] = translations;
    if (idx % 10 === 0) saveCheckpoint(checkpoint);
  }
  // Eredeti + összes fordítás mentése egy sorban (jsonl)
  writer.write(JSON.stringify({ original: item, translations }) + '\n');
}

// Fő pipeline
async function main() {
  const datasetUrl = '';
  const localfile = path.join(os.tmpdir(), 'DuetQA-Verified.jsonl');
  // 1. letöltés ha kell, vagy folytatás checkpointtal
  if (!fs.existsSync(localfile)) {
    console.log("Letöltés...", datasetUrl);
    await downloadDataset(datasetUrl, localfile);
    console.log("Letöltve:", localfile);
  }
  const checkpoint = loadCheckpoint();
  // 2. output megnyitása append-módban, új vagy folytató
  const writer = fs.createWriteStream(OUTPUT_FILE, { flags: 'a' });
  const fileStream = fs.createReadStream(localfile);
  const rl = readline.createInterface({ input: fileStream });

  let idx = 0, apiKeyIdx = 0;
  for await (const line of rl) {
    if (!line.trim()) continue;
    let item = {};
    try { item = JSON.parse(line); }
    catch (e) { continue; }
    if (checkpoint[idx]) {
      // Már lefordítottuk, ugorjunk
      idx++;
      continue;
    }
    await translateAndSaveAll(item, apiKeyIdx, checkpoint, writer, idx);
    apiKeyIdx++;
    idx++;
    // Rate protection, ha kell throttling vagy sleep, használj minute-level limitet
    await new Promise(res => setTimeout(res, 1100)); // kb 1 kérdés/mp 1 thread esetén
  }
  writer.end();
  saveCheckpoint(checkpoint);
  console.log('Kész!');
}

main().catch(err => {
  console.error(err);
  process.exit(1);
});

