A Cerebras API rate limitek és a modellek specifikációi alapján optimalizálom a kódot **maximum sebességre és teljesítményre**, csak valós, éles megoldásokkal.[1]

## Optimalizált Production-Ready Kód

```javascript
// app/main.js
const fs = require('fs');
const path = require('path');
const os = require('os');
const https = require('https');
const { pipeline } = require('stream');
const readline = require('readline');
const Cerebras = require('@cerebras/cerebras_cloud_sdk');
const { Worker } = require('worker_threads');
const pLimit = require('p-limit');

// API kulcsok - FIGYELEM: Éles környezetben ENV változóban tárolandók!
const apiKeys = [
  process.env.CEREBRAS_KEY_1 || "csk-jw6drkvjmyfwfwxpfmc8rx32v6j8kpm93ymt8vdt8nw882vd",
  process.env.CEREBRAS_KEY_2 || "csk-f2vt69wh63pkny4rd3pwdh88m2nyvm9yp8dwk9ynx2d83vfy",
  process.env.CEREBRAS_KEY_3 || "csk-6k3jvehx4dr8524856ck5j32erjtjet86dxpy9fyd9nwedft"
];

const OUTPUT_FILE = path.join(__dirname, 'DuetQA-Verified-multilingual.jsonl');
const CHECKPOINT_FILE = path.join(__dirname, 'DuetQA-Verified-checkpoint.json');
const TEMP_DIR = path.join(__dirname, 'temp_chunks');

// Rate limit optimalizált értékek a Cerebras dokumentáció alapján
const MODEL1 = "gpt-oss-120b";        // 30 RPM, 60K TPM
const MODEL2 = "qwen-3-coder-480b";   // 10 RPM, 150K TPM

// Célnyelvek
const languages = [
  "magyar", "török", "finn", "észt", "tamil", "kannada", "telugu", "koreai", "japán", "zulu", 
  "szuahéli", "inuktitut", "st. lawrence island yupik", "yupik", "mohawk", "nahuatl", "orosz", 
  "izlandi", "szlovén", "arab", "perzsa", "urdu", "görög", "vietnami", "mandarin kínai", "angol", 
  "spanyol", "portugál", "hindí", "bengáli", "indonéz", "maláj", "ubyh", "grúz", "szuahéli", "zulu"
];

// Concurrency limiter kulcsonként és modellenként
const limiters = {
  model1: apiKeys.map(() => pLimit(28)),  // 30 RPM alatt maradunk
  model2: apiKeys.map(() => pLimit(8))    // 10 RPM alatt maradunk
};

function getAvailableApiKey(index) {
  return apiKeys[index % apiKeys.length];
}

function getApiKeyIndex(globalIndex) {
  return globalIndex % apiKeys.length;
}

// Dataset letöltés optimalizált chunkolással
function downloadDataset(url, dest) {
  return new Promise((resolve, reject) => {
    const file = fs.createWriteStream(dest);
    https.get(url, response => {
      if (response.statusCode !== 200) {
        return reject(new Error('HTTP ' + response.statusCode));
      }
      pipeline(response, file, err => err ? reject(err) : resolve());
    }).on('error', reject);
  });
}

function loadCheckpoint() {
  try {
    if (!fs.existsSync(CHECKPOINT_FILE)) return { processed: {}, failed: {} };
    return JSON.parse(fs.readFileSync(CHECKPOINT_FILE, 'utf8'));
  } catch (e) { 
    return { processed: {}, failed: {} }; 
  }
}

function saveCheckpoint(obj) {
  fs.writeFileSync(CHECKPOINT_FILE, JSON.stringify(obj, null, 2));
}

// Exponenciális backoff retry logika rate limitek kezelésére
async function retryWithBackoff(fn, maxRetries = 5, baseDelay = 1000) {
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (err) {
      const isRateLimit = err.status === 429 || err.message?.includes('rate limit');
      const isServerError = err.status >= 500;

      if ((isRateLimit || isServerError) && i < maxRetries - 1) {
        const delay = baseDelay * Math.pow(2, i) + Math.random() * 1000;
        console.log(`Retry ${i + 1}/${maxRetries} késleltetés: ${Math.round(delay)}ms`);
        await new Promise(res => setTimeout(res, delay));
        continue;
      }
      throw err;
    }
  }
}

// Optimalizált fordítás batch-ekben, párhuzamosan
async function translateSingleLanguage(item, lang, apiKey, model, keyIndex) {
  const limiter = model === MODEL1 ? limiters.model1[keyIndex] : limiters.model2[keyIndex];

  return limiter(() => retryWithBackoff(async () => {
    const client = new Cerebras({ apiKey });

    const prompt = `Fordítsd le a következő QA párost erre a nyelvre: ${lang}

Kérdés: "${item.question?.trim() || item.question}"
Válasz: "${item.answer?.trim() || item.answer}"

Adj természetes, anyanyelvi szintű fordítást JSON formátumban: {"question": "...", "answer": "..."}`;

    const response = await client.chat.completions.create({
      messages: [
        { 
          role: "system", 
          content: "Precíz, anyanyelvi szintű fordító vagy. Csak JSON formátumban válaszolj." 
        },
        { role: "user", content: prompt }
      ],
      model,
      stream: false,
      max_completion_tokens: 4096,
      temperature: 0.04,
      top_p: 0.02
    });

    const content = response.choices?.[0]?.message?.content || '{}';

    try {
      return JSON.parse(content.trim());
    } catch (e) {
      // JSON parse hiba esetén regex-szel kinyerjük
      const jsonMatch = content.match(/\{[\s\S]*"question"[\s\S]*"answer"[\s\S]*\}/);
      if (jsonMatch) {
        return JSON.parse(jsonMatch[0]);
      }
      return { question: content, answer: `Parse hiba: ${lang}` };
    }
  }, 5, 2000));
}

// Párhuzamos nyelvek fordítása API kulcsok és rate limitek optimális kihasználásával
async function translateAndSaveAll(item, idx, checkpoint, writer) {
  if (checkpoint.processed[idx]) {
    return; // Már kész
  }

  const translations = {};
  const translationPromises = [];

  // Nyelvek elosztása az API kulcsok között
  for (let li = 0; li < languages.length; li++) {
    const lang = languages[li];
    const keyIndex = (li + idx) % apiKeys.length;
    const apiKey = apiKeys[keyIndex];
    const model = (lang === "magyar") ? MODEL1 : MODEL2;

    translationPromises.push(
      translateSingleLanguage(item, lang, apiKey, model, keyIndex)
        .then(result => {
          translations[lang] = result;
        })
        .catch(err => {
          console.error(`Hiba ${lang} fordításnál (idx:${idx}):`, err.message);
          translations[lang] = { 
            question: `HIBA: ${lang}`, 
            answer: err.message || "Ismeretlen hiba" 
          };
        })
    );
  }

  // Várjuk meg az összes fordítást
  await Promise.all(translationPromises);

  // Mentés JSONL formátumban
  const record = {
    id: idx,
    original: {
      question: item.question,
      answer: item.answer
    },
    translations
  };

  writer.write(JSON.stringify(record) + '\n');
  checkpoint.processed[idx] = true;

  // Checkpoint mentés minden 5. elem után
  if (idx % 5 === 0) {
    saveCheckpoint(checkpoint);
  }
}

// Batch feldolgozás méretének dinamikus beállítása
function calculateOptimalBatchSize() {
  const totalRPM = apiKeys.length * 10; // qwen-3-coder-480b limitje a szűkebb
  return Math.floor(totalRPM / 2); // Biztonsági margó
}

// Fő pipeline párhuzamos batch feldolgozással
async function main() {
  const datasetUrl = '';
  const localfile = path.join(os.tmpdir(), 'DuetQA-Verified.jsonl');

  console.log('Indítás:', new Date().toISOString());

  // 1. Letöltés ha szükséges
  if (!fs.existsSync(localfile)) {
    console.log('Dataset letöltése:', datasetUrl);
    await downloadDataset(datasetUrl, localfile);
    console.log('Letöltve:', localfile);
  }

  const checkpoint = loadCheckpoint();
  const writer = fs.createWriteStream(OUTPUT_FILE, { flags: 'a' });

  // 2. Adatok beolvasása
  const items = [];
  const fileStream = fs.createReadStream(localfile);
  const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

  for await (const line of rl) {
    if (!line.trim()) continue;
    try {
      const item = JSON.parse(line);
      items.push(item);
    } catch (e) {
      console.error('JSON parse hiba:', e.message);
    }
  }

  console.log(`Összesen ${items.length} tétel feldolgozásra vár`);
  console.log(`Már feldolgozva: ${Object.keys(checkpoint.processed).length} tétel`);

  // 3. Batch feldolgozás párhuzamosan
  const batchSize = calculateOptimalBatchSize();
  console.log(`Batch méret: ${batchSize} párhuzamos feldolgozás`);

  const batchLimit = pLimit(batchSize);
  const processingPromises = [];

  for (let idx = 0; idx < items.length; idx++) {
    if (checkpoint.processed[idx]) {
      continue; // Már feldolgozva
    }

    processingPromises.push(
      batchLimit(() => translateAndSaveAll(items[idx], idx, checkpoint, writer))
    );
  }

  // Várjuk meg az összes feldolgozást
  await Promise.all(processingPromises);

  writer.end();
  saveCheckpoint(checkpoint);

  console.log('Feldolgozás befejezve:', new Date().toISOString());
  console.log(`Output fájl: ${OUTPUT_FILE}`);
}

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('\nLeállítás... checkpoint mentése...');
  saveCheckpoint(loadCheckpoint());
  process.exit(0);
});

process.on('uncaughtException', (err) => {
  console.error('Nem kezelt kivétel:', err);
  saveCheckpoint(loadCheckpoint());
  process.exit(1);
});

main().catch(err => {
  console.error('Fő hiba:', err);
  saveCheckpoint(loadCheckpoint());
  process.exit(1);
});
